local uun=buffer.create(aadb(#ebwz/5)*4);
do local lbbd,fuls,ab=0,0,0;
while ab<#ebwz do
fuls=0;
for pe=1,5 do fuls=fuls*85+bw[string.byte(ebwz,ab+pe)];end;
ab=ab+5;
buffer.writeu8(uun,lbbd,aadb(fuls/16777216));
buffer.writeu8(uun,lbbd+1,aadb(fuls/65536)%256);
buffer.writeu8(uun,lbbd+2,aadb(fuls/256)%256);
buffer.writeu8(uun,lbbd+3,fuls%256);
lbbd=lbbd+4;end;end;
local ot=buffer.create(0x23bf2);
local abqt={128,64,32,16,8,4,2,1};
local fj,yrmk,gjd=0,0,0x14b48;
while fj<gjd do
local gzh=buffer.readu8(uun,fj);
fj=fj+1;
for fuit=1,8 do
if fj>=gjd then break;end;
if gzh>=abqt[fuit] then gzh=gzh-abqt[fuit];
local vk=buffer.readu8(uun,fj+1)+buffer.readu8(uun,fj)*256+1;
local nt=buffer.readu8(uun,fj+2)+4;
fj=fj+3;
local fo=yrmk-vk;
for pe=0,nt-1 do buffer.writeu8(ot,yrmk+pe,buffer.readu8(ot,fo+pe));end;
yrmk=yrmk+nt;
else
buffer.writeu8(ot,yrmk,buffer.readu8(uun,fj));fj=fj+1;yrmk=yrmk+1;
end;end;end;
local tosx=0;
